# Simulate checking local constraints on a small N=4 board
N = 4
# Marked cells (0-indexed: (0,0), (0,1), (1,0), (1,1))
marked = set([(0, 0), (0, 1), (1, 0), (1, 1)])

def is_marked(r, c):
    return (r, c) in marked

# Check all possible local domino placements centered around the marked block
forbidden_dominoes = []

# Check horizontal dominoes
for r in range(N):
    for c in range(N - 1):
        if is_marked(r, c) and is_marked(r, c + 1):
            forbidden_dominoes.append((r, c, 'H'))

# Check vertical dominoes
for r in range(N - 1):
    for c in range(N):
        if is_marked(r, c) and is_marked(r + 1, c):
            forbidden_dominoes.append((r, c, 'V'))

print(f"Total forbidden dominoes found due to internal markings: {len(forbidden_dominoes)}")

# Check the core constraint:
if len(forbidden_dominoes) > 0:
    print("Constraint successfully restricts internal tiling choices.")
else:
    print("Error: Constraints are ineffective.")

